using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ObserverMemory.Algorithms;

internal sealed class UniformDescriptorSupportDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/ObserverMemory/Algorithms/UniformDescriptorSupport.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Effective original presentations and exact same-source native halt support.",
        H("Effective presentations and exact native halt support"),
        Blocks(
            Paragraph(Text("The full register carrier S contains a subtype D of original sources. Update acts on S and need not preserve D. Read observes U iterated j times on the original source. A chart constructor accepts only admitted coordinates; the disjoint chart union is bijective with D, including empty families and zero-dimensional charts. Complete target rows and their supplied default are retained as actual data.")),
            Describe.Lean(DescribeId.Create("task"), Handle("Task"),
                H("The original task"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The permitted physical domain consists of finite words over a supplied finite alphabet, with effective membership. Replies have a fixed nonempty finite order. The supplied target returns the entire row of an original source; it is never computed from an arbitrary transported register."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("presentation"), Handle("Presentation"),
                H("Exact supplied maps and predicates"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Admission, whole-row Same, descriptor validity and all-source all-epoch Reply are actual Presburger syntax. Theta, literal choice, literal coverage and complete-row construction are supplied implementation data. Semantic assumptions are proof fields. Coverage says membership in Real, and permits a noncanonical physical realization. Descriptor choice has no source, chart or epoch argument."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("reachedtransport"), Handle("ReachedTransport"),
                H("Reached content, absence and rank"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Content is defined only on reached registers. Persistence, its additive transport action and nondecreasing decoded rank retain the reached-address interpretation. The absent symbol, when present, has rank zero. The finite rank map strictly preserves the given reply order."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("rank-monotone"), Handle("rank_monotone"),
                H("Rank monotonicity on one original source"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Direct substitution of the supplied decode and transport laws, with the zero-rank minimum in the absent case, gives monotonicity at every permitted literal on the same original source. The transported register is used directly; no source constructor or chart inverse is applied after update."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("installedentry"), Handle("InstalledEntry"),
                H("Stored instructions"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A read stores one permitted literal and a tabulated vector of reply successors. An update stores one successor. A halt stores one complete row. No descriptor, chart selector, source coordinate, phase witness or epoch port is installed."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("installedtable"), Handle("InstalledTable"),
                H("A complete materialized installation"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The initial state and every entry are present in an eager vector, including unreachable entries. A runtime function which invokes a solver, realizer, Theta or target constructor is not this installation. The data type specifies the storage boundary; arithmetic witness extraction constructs it separately."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("successful"), Handle("Successful"),
                H("Literal execution with the stored row"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original source, a native finite Run reaches a halt whose stored complete row equals that source target. This condition is stronger than graph Total and Shared alone."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("typedentry"), Handle("TypedEntry"),
                H("Graph and descriptor type choices"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Each read occurrence has its own finite descriptor type and every reply successor. Update and halt choices remain available when the type alphabet is empty. Parameters are not enumerated or numerically bounded."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("reindexskeleton"), Handle("reindexSkeleton"),
                H("Every finite control label is retained"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A supplied equivalence sigma maps the original initial state and each successor. At numeric state i the complete entry is read at sigma inverse i. Every state is retained, including unreachable states. Type assignment is required only at original reads, so no artificial type inhabitant is needed for read-free tables."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("entrylist"), Handle("entryList"),
                H("All entry alternatives"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Explicit finite products enumerate every type and every reply-successor vector, every update successor, and halt. Successors are eagerly tabulated vectors."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("skeletonlist"), Handle("skeletonList"),
                H("All complete labeled skeletons"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("An explicit product enumerates each initial state and every state entry. No reachability pruning or numerical descriptor cutoff occurs."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("skeletonlist-complete"), Handle("skeletonList_complete"),
                H("Enumeration has no missing skeleton"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every complete typed skeleton belongs to the executable list by List.mem_pi, List.mem_map and List.mem_flatMap. These consumed product bindings preserve all entries. The retained symbolicTable construction uses reindexSkeleton; native state and address transport supplies its operational correspondence."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("candidates"), Handle("candidates"),
                H("All sizes one through K"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The list contains every skeleton of each positive size at most K. Budget zero gives the empty list. Empty descriptor types leave update and halt graphs intact."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("blockindex"), Handle("blockIndex"),
                H("Fixed numeric descriptor blocks"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Read occurrence a has offset equal to the sum of all earlier descriptor dimensions. Its local parameter k has numeric index offset plus k. The total is the sum of all block widths; a zero-width block contributes no coordinate."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("blockindex-injective"), Handle("blockIndex_injective"),
                H("Different blocks do not overlap"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The pinned finSigmaFinEquiv and finSigmaFinEquiv_apply identify this offset map with the standard finite sigma equivalence; List.sum_take_ofFn supplies the prefix-sum correspondence. This consumed binding gives disjoint numeric intervals for distinct read occurrences. Two occurrences may install the same physical literal while keeping distinct descriptor blocks. Every visit and every phase formula uses the same blockIndex map."))),
                DescribeRole.Theorem),
            Paragraph(Text("This syntax is the arithmetic component of the whole literal-table synthesis. It consumes the native fixed-response path and final-unit-update crossing formulas and the native phase partition theorem. Supplied presentation maps interpret only admitted source tuples. The formulas contain one common descriptor tuple and one source tuple shared by every phase.")),
            Describe.Lean(DescribeId.Create("closeex"), Handle("closeEx"),
                H("Capture-avoiding block quantification"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The existing Presburger bounded-formula relabel and exs APIs bind an explicitly sized numeric block. closeAll uses the corresponding universal API. Empty quantifier blocks retain their logical meaning."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("allf"), Handle("allF"),
                H("Finite conjunction and disjunction"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The list folds use true for empty conjunction and false for empty disjunction. anyF forms the disjunction. These are actual existing Presburger syntax, not an additional arithmetic language."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gamma"), Handle("gamma"),
                H("Exact shared-source epoch guards"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every guarded epoch reads the same free source tuple and the same descriptor block for each occurrence. Source variables, descriptor variables, guard endpoints and the bound epoch have disjoint tagged embeddings. For D descriptor coordinates and d source coordinates, the standard finSumFinEquiv flattening sends descriptor k to k and source i to D+i. In a phase body the terminal epoch has index D+d, phase endpoint t_i has index D+d+1+i, and phase count d_i has index D+d+1+(l+2)+i. The guard-bound epoch is a fresh inner quantifier. Constructor separation and the capture-avoiding relabel realization equations prove these blocks do not alias. The independent Shared source m has index D+d+m in its two-source scope; each H binds its own fresh terminal epoch and phase block."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("phasedisjunct"), Handle("phaseDisjunct"),
                H("A native phase chain in finite syntax"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("All phase endpoints and update counts are independently bound. Internal crossings finish in a genuine unit update. The last path ends at J, while J plus one is only the right delimiter of its guard. Graph coefficients in path progressions are computed numerals; no two unbounded variables are multiplied."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("haltepochformula"), Handle("haltEpochFormula"),
                H("A finite complete phase enumeration"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The list ranges over every permitted phase count, every response vector at each phase and every intermediate control. The maximum rank times the number of actual reads bounds phase count only, with no bound on phase duration, runtime, epochs or literal length."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("dims"), Handle("dims"),
                H("Dimensions for actual read occurrences"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The explicit finite subtype enumeration lists exactly read controls. Each selected type supplies its own numeric dimension, including zero. No artificial observation port is added to the installed control state."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("descriptortuple"), Handle("descriptorTuple"),
                H("One assignment reused at every visit"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every local coordinate is read through the fixed blockIndex of its occurrence. The resulting descriptor is shared across all charts, epochs and phase visits."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("realizes"), Handle("Realizes"),
                H("All permitted realizations"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A literal assignment requires Real membership for each descriptor. It permits duplicates and noncanonical choices. It requires no equality to chosenLiterals."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("haltat"), Handle("haltAt"),
                H("Original-source halt at an unbounded epoch"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The native phase formula is instantiated with the original source chart, its admission and exact descriptor replies. Its eventual projection H independently quantifies that source terminal epoch."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-support"), Handle("native_support"),
                H("Exact native literal execution"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("On admitted coordinates and a valid common tuple, haltAt is equivalent to native Run at J, and H is equivalent to existence of a native Run at some J. The theorem accepts every Real-compatible literal assignment. Arbitrary noninjective address transport identifies occurrence observations with the physical literal program. A halt endpoint gives the native first-arrival interpretation; the theorem also keeps general finite endpoints exact. It certifies no stored output row."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("literalprogram"), Handle("literalProgram"),
                H("Proof interpretation of the literal graph"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("This map interprets the graph through the native arbitrary-address transport API. It supplies native execution semantics for proofs. It is not asserted to be a stored table, and does not construct any halt row."))),
                DescribeRole.Definition))));

    private static DeclarationHandle Handle(string name) => DeclarationHandle.Create(Owner + name);
}
